snippet_css:
:root{
  --bg: #14213D;
  --fg: #FBF7EE;
  --muted: #D5CEBC;
  --surface: rgba(255,255,255,.06);
  --border: rgba(230,209,146,.38);
  --accent: #E6D192;
  --accent-fg: #14213D;
  --accent-grad: linear-gradient(120deg,#8C6F2E,#F3E4B0 45%,#BFA05A 55%,#8C6F2E);
  --radius: 3px;
  --radius-sm: 2px;
  --shadow: 0 18px 40px rgba(0,0,0,.45);
  --btn-shadow: 0 0 0 1px rgba(230,209,146,.45),0 10px 24px rgba(191,160,90,.20);
  --art-bg: radial-gradient(circle at 34% 30%,#FBF7EE,#F3E4B0 34%,#BFA05A 62%,#14213D);
  --media-bg: linear-gradient(140deg,#1E2C4C,#3A4766);
  --cta-bg: linear-gradient(140deg,#1B2743,#2A3960);
  --input-bg: #16233F;
  --ok: #9BD8B0;
  --warn: #E9A38E;
  --font-display: 'Cormorant Garamond','Noto Serif TC',serif;
  --font-body: Lora,'Noto Serif TC',serif;
  --font-mono: ui-monospace,'SF Mono',Menlo,monospace;
  --focus-ring: var(--accent);
}

